<?php
$isProjects=$view==='projects';
$layout=is_string($_GET['layout']??null)&&$_GET['layout']==='cards'?'cards':'list';
$pageUrl=$view==='overview'?'./':'./'.$view.'.php';
$status=is_string($_GET['status']??null)?$_GET['status']:'';
if(!in_array($status,['Upcoming','Under construction','Completed'],true))$status='';
$items=$filtered;
if($isProjects){
 $items=[];
 foreach(require dirname(__DIR__).'/Config/projects.php' as $p){
  if(($query===''||mb_stripos($p[0].' '.$p[1],$query)!==false)&&($status===''||$p[3]===$status))$items[]=['title'=>$p[0],'city'=>$p[1],'type'=>$p[2],'status'=>$p[3],'progress'=>$p[4],'image'=>'./assets/properties/'.$p[5].'.png'];
 }
}
function adminItemUrl(array $item,bool $project): string {return $project?'../projects?q='.rawurlencode($item['title']):'../property.php?slug='.rawurlencode($item['slug']);}
?>
<section class="panel inventory"><div class="panel-title"><div><h2><?= $isProjects?'Project inventory':'Property inventory' ?></h2><p><?= count($items) ?> sample <?= $isProjects?'projects':'properties' ?> found</p></div><div class="layout-switch" aria-label="Display layout"><?php foreach(['cards'=>'Cards','list'=>'List'] as $value=>$label): $params=['layout'=>$value,'q'=>$query];if($isProjects)$params['status']=$status;else $params['purpose']=$purpose; ?><a href="<?= e($pageUrl.'?'.http_build_query($params)) ?>" <?= $layout===$value?'aria-current="true"':'' ?>><?= listingIcon($value==='cards'?'grid':'filter') ?><?= e($label) ?></a><?php endforeach; ?></div></div>
<form class="table-toolbar" method="get" action="<?= e($pageUrl) ?>"><input type="hidden" name="layout" value="<?= e($layout) ?>"><label class="search-field"><?= listingIcon('search') ?><span class="sr-only">Search <?= $isProjects?'projects':'properties' ?></span><input name="q" type="search" value="<?= e($query) ?>" placeholder="Search name or location..."></label><label><span class="sr-only"><?= $isProjects?'Project status':'Listing purpose' ?></span><select name="<?= $isProjects?'status':'purpose' ?>"><option value="">All <?= $isProjects?'statuses':'listings' ?></option><?php foreach($isProjects?['Upcoming','Under construction','Completed']:['Rent','Sell'] as $option): ?><option <?= ($isProjects?$status:$purpose)===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="primary-button" type="submit">Filter</button><?php if($query!==''||($isProjects?$status:$purpose)!==''): ?><a class="text-link" href="<?= e($pageUrl.'?layout='.$layout) ?>">Reset</a><?php endif; ?></form>
<?php if(!$items): ?><div class="empty-state">No <?= $isProjects?'projects':'properties' ?> match your filters. Try another search or reset filters.</div>
<?php elseif($layout==='cards'): ?><div class="admin-inventory-grid"><?php foreach($items as $item): ?><article class="inventory-card"><a href="<?= e(adminItemUrl($item,$isProjects)) ?>" aria-label="View <?= e($item['title']) ?>"><img src="../<?= e(substr($item['image'],2)) ?>" alt="Illustrative image for <?= e($item['title']) ?>" width="512" height="340" loading="lazy"></a><div><span class="subtle-tag"><?= e($isProjects?$item['status']:$item['purpose']) ?></span><h3><a href="<?= e(adminItemUrl($item,$isProjects)) ?>"><?= e($item['title']) ?></a></h3><p><?= e($item['city']) ?> &middot; <?= e($item['type']) ?></p><?php if($isProjects): ?><label class="inventory-progress">Sample progress <strong><?= $item['progress'] ?>%</strong><progress max="100" value="<?= $item['progress'] ?>"><?= $item['progress'] ?>%</progress></label><?php else: ?><p><?= $item['beds'] ?> beds &middot; <?= number_format($item['area']) ?> sq.ft</p><strong class="inventory-price"><?= e(listingPrice($item)) ?><?= $item['purpose']==='Rent'?' / month':'' ?></strong><?php endif; ?><a class="inventory-view" href="<?= e(adminItemUrl($item,$isProjects)) ?>">View <?= $isProjects?'project':'property' ?> &nearr;</a></div></article><?php endforeach; ?></div>
<?php else: ?><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $isProjects?'Projects':'Properties' ?> list"><table class="mobile-card-table"><thead><tr><th><?= $isProjects?'Project':'Property' ?></th><th>Location</th><th>Type</th><th><?= $isProjects?'Status':'Purpose' ?></th><th><?= $isProjects?'Sample progress':'Price' ?></th><th><span class="sr-only">Details</span></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td class="mobile-card-heading"><div class="property-cell"><img src="../<?= e(substr($item['image'],2)) ?>" alt="" width="58" height="48" loading="lazy"><div><strong><?= e($item['title']) ?></strong><span>Sample <?= $isProjects?'project concept':($item['beds'].' beds · '.number_format($item['area']).' sq.ft') ?></span></div></div></td><td data-label="Location"><?= e($item['city']) ?></td><td data-label="Type"><?= e($item['type']) ?></td><td data-label="<?= $isProjects?'Status':'Purpose' ?>"><span class="subtle-tag"><?= e($isProjects?$item['status']:$item['purpose']) ?></span></td><td class="price-cell" data-label="<?= $isProjects?'Progress':'Price' ?>"><?php if($isProjects): ?><?= $item['progress'] ?>%<progress class="table-progress" max="100" value="<?= $item['progress'] ?>"><?= $item['progress'] ?>%</progress><?php else: ?><?= e(listingPrice($item)) ?><?= $item['purpose']==='Rent'?'<small>/ month</small>':'' ?><?php endif; ?></td><td data-label="Details"><a class="detail-link" href="<?= e(adminItemUrl($item,$isProjects)) ?>" aria-label="View <?= e($item['title']) ?>">&nearr;</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<p class="inventory-note">Sample content only. <?= $isProjects?'Progress is illustrative; these are not live project announcements.':'Listings are not verified live offers.' ?></p></section>
